  get diceSet() { return diceSet; },
  setDiceSet(id) { return setDiceSet(id); },
  get physics() { return { ...PHYS }; },
  setPhysics(p) { return setPhysics(p); },
  // The three settle instruments (C30c). All inert at their defaults — see
